def solve(inputs: dict) -> float:
    terms = inputs.get('terms', [])

    if not terms:
        return 0

    # Initialize with standard continued fraction convergent algorithm
    p_prev = 1
    p = terms[0]

    # Apply the recurrence relation p <- a*p + p_prev for each term
    for i in range(1, len(terms)):
        p_new = terms[i] * p + p_prev
        p_prev = p
        p = p_new

    return float(p)

